from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

@task(returns=1)
def compute_element(alpha, x_i, y_i):
    val = alpha * x_i + y_i
    return val


def main(alpha, x, y, N):
    if alpha == 0:
        z = [0] * N
        for item in y:
            index = item['index']
            value = item['value']
            z[index] = value
        return z

    y_dict = {item['index']: item['value'] for item in y}

    futures = []
    indices = []
    for item in x:
        index = item['index']
        value = item['value']
        y_value = y_dict.pop(index, 0)

        futures.append(compute_element(alpha, value, y_value))
        indices.append(index)

    results = compss_wait_on(futures)

    z = [0] * N
    for index, value in zip(indices, results):
        z[index] = value

    for index, value in y_dict.items():
        z[index] = value

    return z
